initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Update Context Source Registration with Response Status Code set to 400     and
        Update Context Source Registration with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData'     and
        Update Context Source Registration with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceRegistrations/{context_source_registration_id}'
        method set to 'PATCH'
        Update Context Source Registration with CSR Id set to '${registration_id}' and subscription update fragment set to 'context-source-registration-invalid-sample.jsonld'
}
